OR testing_products.sort_order IS NOT excluded.sort_order;
INSERT INTO testing_products (id,sku,name,partner,test_type,supplier_state,markers_json,description,sample,result_time,results_access,limitations,source_url,source_checked,supplier_retail_reference_pence,sort_order) VALUES ('male-hormone','SST-NF-MALE-HORMONE','Male Hormone','Newfoundland','lab','coming_soon','["Testosterone","Free testosterone","Luteinising hormone (LH)","Follicle stimulating hormone (FSH)","Oestradiol","Prolactin","Sex hormone binding globulin (SHBG)","Albumin"]','A forthcoming laboratory panel of hormones and related markers, including total and free testosterone.','Finger-prick blood sample','Timing to be confirmed at launch','Our testing partner’s secure results portal','Hormone results need the right sampling and clinical context. A panel does not establish the cause of every symptom or automatically indicate treatment.','https://www.newfoundland.io/products/male-hormone','2026-10-28',NULL,3) ON CONFLICT(id) DO UPDATE SET name=excluded.name,supplier_state=excluded.supplier_state,markers_json=excluded.markers_json,description=excluded.description,sample=excluded.sample,result_time=excluded.result_time,results_access=excluded.results_access,limitations=excluded.limitations,source_url=excluded.source_url,source_checked=excluded.source_checked,supplier_retail_reference_pence=excluded.supplier_retail_reference_pence,sort_order=excluded.sort_order,revision=testing_products.revision+1,updated_at=CURRENT_TIMESTAMP WHERE testing_products.name IS NOT excluded.name OR testing_products.supplier_state IS NOT excluded.supplier_state OR testing_products.markers_json IS NOT excluded.markers_json OR testing_products.description IS NOT excluded.description OR testing_products.sample IS NOT excluded.sample OR testing_products.result_time IS NOT excluded.result_time OR testing_products.results_access IS NOT excluded.results_access OR testing_products.limitations IS NOT excluded.limitations OR testing_products.source_url IS NOT excluded.source_url OR testing_products.source_checked IS NOT excluded.source_checked OR testing_products.supplier_retail_reference_pence IS NOT excluded.supplier_retail_reference_pence OR testing_products.sort_order IS NOT excluded.sort_order;
